mapper.update:
UPDATE tbl_posts
SET title = #{title},
content = #{content},
category = #{category}
WHERE post_id = #{postId}

mapper.select:
SELECT c.comment_id, c.post_id, c.user_id, u.username AS createdBy, c.content, c.created_at
FROM tbl_comments c
JOIN tbl_users u ON c.user_id = u.user_id
WHERE c.post_id = #{postId}
ORDER BY c.created_at DESC;
